def transform_cc(grid,bg):
 h,w=len(grid),len(grid[0]); out=[[bg]*w for _ in range(h)]; seen=set()
 for r in range(h):
  for c in range(w):
   v=grid[r][c]
   if v==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop(); comp.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      a,b=x+dx,y+dy
